 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))

            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue

            # A rectangular U-shaped frame has a single missing top cell.
            top = [c for c in range(c0, c1 + 1) if grid[r0][c] == 5]
            gaps = [c for c in range(c0, c1 + 1) if grid[r0][c] != 5]
            if len(gaps) != 1 or gaps[0] <= c0 or gaps[0] >= c1:
                continue
            gap = gaps[0]
            if not all(grid[y][c0] == 5 and grid[y][c1] == 5 for y in range(r0, r1 + 1)):
                continue
            if not all(grid[r1][c] == 5 for c in range(c0, c1 + 1)):
                continue

            # Fill the cavity.
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if grid[y][x] == 0:
                        out[y][x] = 2

            # Extend from the top opening toward the side with the longer top run.
            left_run = gap - c0
            right_run = c1 - gap
            direction = -1 if left_run > right_run else 1
            y = r0 - 1
            if 0 <= y < h:
                x = gap
                while 0 <= x < w:
                    out[y][x] = 2
                    x += direction

    return out
